using CTXD.Server.Data;using Npgsql;
namespace CTXD.Server.Services;
public sealed class TeamTimesGrantService(GameDb db,GamePushHub push)
{
 public async Task<int> GrantAsync(long player,int amount,string sourceKey,CancellationToken ct){if(amount<=0||string.IsNullOrWhiteSpace(sourceKey))throw new GameException("TEAM_TIMES_GRANT_INVALID","A positive amount and source key are required.");await using var c=await db.DataSource.OpenConnectionAsync(ct);await using var t=await c.BeginTransactionAsync(ct);await using(var add=new NpgsqlCommand("INSERT INTO player_team_time_grants(player_id,source_key,amount) VALUES($1,$2,$3) ON CONFLICT DO NOTHING",c,t)){add.Parameters.AddWithValue(player);add.Parameters.AddWithValue(sourceKey);add.Parameters.AddWithValue(amount);if(await add.ExecuteNonQueryAsync(ct)==1){await using var grant=new NpgsqlCommand("UPDATE players SET team_times=team_times+$2 WHERE id=$1",c,t);grant.Parameters.AddWithValue(player);grant.Parameters.AddWithValue(amount);if(await grant.ExecuteNonQueryAsync(ct)!=1)throw new GameException("PLAYER_NOT_FOUND","Player does not exist.",404);}}int total;await using(var q=new NpgsqlCommand("SELECT team_times FROM players WHERE id=$1",c,t)){q.Parameters.AddWithValue(player);total=Convert.ToInt32(await q.ExecuteScalarAsync(ct));}await t.CommitAsync(ct);await push.SendAsync(player,"team.updated",new{reason="teamTimes.granted",teamTimes=total},ct);return total;}
}
